// Compose each folder demo's `styles.css` from the shared fragment registry
// plus the demo's own `styles.json` manifest. The output is a real CSS file
// that App.vue imports, so Vite extracts it into the prerendered docs page
// (SSR-safe, no flash of unstyled content) and the playground's `?raw` glob
// seeds it into the REPL iframe. Generated files are gitignored; this runs in
// dev/build (package.json), as a Nuxt dev plugin (live reload, nuxt.config),
// and in the test setup (vitest.config) so every consumer resolves the import.

import { readdirSync, existsSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, resolve, join } from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'
import { core, fragments } from './registry.mjs'

const here = dirname(fileURLToPath(import.meta.url))
const demosDir = resolve(here, '../../docs-demos')

const FRAGMENT_NAMES = Object.keys(fragments)

const BANNER = `/* GENERATED by apps/site/scripts/demo-styles/codegen.mjs (do not edit).
   Composed from registry.mjs + this demo's styles.json ({ "with": [...] }).
   Regenerated on dev/build and gitignored. See ../README.md. */`

function composeCss(withList) {
  const seen = new Set()
  for (const name of withList) {
    if (!(name in fragments)) {
      throw new Error(
        `[demo-styles] unknown fragment "${name}". ` +
          `Valid fragments: ${FRAGMENT_NAMES.join(', ')}.`
      )
    }
    seen.add(name)
  }
  const selected = FRAGMENT_NAMES.filter((name) => seen.has(name))
  const blocks = [BANNER, core.trim(), ...selected.map((name) => fragments[name].trim())]
  return blocks.join('\n\n') + '\n'
}

function readManifest(folder) {
  const manifestPath = join(folder, 'styles.json')
  // Read directly and treat ENOENT as "no manifest" rather than
  // existsSync-then-read, whose gap is a check-then-use file-system race.
  let raw
  try {
    raw = readFileSync(manifestPath, 'utf8')
  } catch (error) {
    if (error.code === 'ENOENT') return []
    throw new Error(`[demo-styles] ${manifestPath} could not be read: ${error.message}`)
  }
  let parsed
  try {
    parsed = JSON.parse(raw)
  } catch (error) {
    throw new Error(`[demo-styles] ${manifestPath} is not valid JSON: ${error.message}`)
  }
  const list = parsed?.with ?? []
  if (!Array.isArray(list) || list.some((name) => typeof name !== 'string')) {
    throw new Error(`[demo-styles] ${manifestPath}: "with" must be an array of fragment names.`)
  }
  return list
}

function writeIfChanged(file, content) {
  // Read-and-compare instead of existsSync-then-read-then-write: folding the
  // existence check into the read closes the check-then-use file-system race
  // CodeQL flags (js/file-system-race) while preserving the skip-identical
  // write that keeps codegen idempotent for the dev watcher.
  let existing
  try {
    existing = readFileSync(file, 'utf8')
  } catch {
    existing = undefined
  }
  if (existing === content) return false
  writeFileSync(file, content)
  return true
}

function demoFolders() {
  return readdirSync(demosDir, { withFileTypes: true })
    .filter((entry) => entry.isDirectory())
    .map((entry) => join(demosDir, entry.name))
    .filter((folder) => existsSync(join(folder, 'App.vue')))
}

// Regenerate a single demo folder's styles.css. Returns true if it changed.
export function generateOne(folder) {
  if (!existsSync(join(folder, 'App.vue'))) return false
  return writeIfChanged(join(folder, 'styles.css'), composeCss(readManifest(folder)))
}

// Regenerate every folder demo. Returns a small summary for logging.
export function generateAll() {
  const folders = demoFolders()
  let written = 0
  for (const folder of folders) if (generateOne(folder)) written++
  return { demos: folders.length, written }
}

const invokedDirectly =
  process.argv[1] !== undefined && import.meta.url === pathToFileURL(process.argv[1]).href
if (invokedDirectly) {
  const { demos, written } = generateAll()
  console.log(`[demo-styles] ${demos} demo(s) scanned, ${written} styles.css written.`)
}
